package org.apache.parquet.filter2;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.File;
import java.io.FileNotFoundException;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import org.junit.jupiter.params.provider.ValueSource;

/**
 * Tests for {@link IncrementallyUpdatedFilterPredicateGenerator#run()}.
 *
 * <p>{@code run()} has exactly one observable effect: it writes the source of {@code
 * org.apache.parquet.filter2.recordlevel.IncrementallyUpdatedFilterPredicateBuilder} into the file
 * handed to the generator through its constructor, and closes that file afterwards. All assertions
 * below inspect the generated source.
 */
class IncrementallyUpdatedFilterPredicateGeneratorRunTests {

  /** The primitive types the generator emits an explicit type branch for. */
  private static final String[] TYPES = {"Integer", "Long", "Boolean", "Float", "Double", "Binary"};

  /** The operators that get their own typed visit method on the generated builder. */
  private static final String[] OPERATORS = {
    "Eq", "NotEq", "In", "NotIn", "Contains", "Lt", "LtEq", "Gt", "GtEq", "UserDefined", "LogicalNotUserDefined"
  };

  /**
   * Every type is dispatched on in the eight typed visit methods of the builder itself, in the eight
   * typed visit methods of {@code ContainsInspectorVisitor} and in the two user defined predicate
   * visit methods.
   */
  private static final int BRANCHES_PER_TYPE = 8 + 8 + 2;

  @TempDir
  Path tempDir;

  private Path generatedFile() {
    return tempDir.resolve(
        "org/apache/parquet/filter2/recordlevel/IncrementallyUpdatedFilterPredicateBuilder.java");
  }

  /** Runs the generator into a fresh file and returns the produced source. */
  private String generate() throws IOException {
    Path target = generatedFile();
    Files.createDirectories(target.getParent());
    new IncrementallyUpdatedFilterPredicateGenerator(target.toFile()).run();
    return read(target);
  }

  private static String read(Path file) throws IOException {
    return new String(Files.readAllBytes(file), StandardCharsets.UTF_8);
  }

  /** Joins the given lines, used to build exact multi line expectations. */
  private static String lines(String... lines) {
    return String.join("\n", lines);
  }

  private static int occurrences(String text, String needle) {
    int count = 0;
    int index = text.indexOf(needle);
    while (index >= 0) {
      count++;
      index = text.indexOf(needle, index + needle.length());
    }
    return count;
  }

  private static void assertContains(String text, String expected) {
    assertTrue(text.contains(expected), () -> "generated source is missing:\n" + expected);
  }

  @Test
  void runWritesPackageImportsAndClassHeader() throws IOException {
    String text = generate();

    assertTrue(
        text.startsWith("package org.apache.parquet.filter2.recordlevel;\n"),
        "generated source must start with the recordlevel package declaration");
    for (String imported : new String[] {
      "java.util.Iterator",
      "java.util.List",
      "java.util.Set",
      "org.apache.parquet.hadoop.metadata.ColumnPath",
      "org.apache.parquet.filter2.predicate.FilterPredicate",
      "org.apache.parquet.filter2.predicate.Operators",
      "org.apache.parquet.filter2.predicate.UserDefinedPredicate",
      "org.apache.parquet.io.api.Binary",
      "org.apache.parquet.io.PrimitiveColumnIO",
      "org.apache.parquet.schema.PrimitiveComparator"
    }) {
      assertContains(text, "import " + imported + ";\n");
    }
    assertContains(
        text,
        "This class is auto-generated by org.apache.parquet.filter2.IncrementallyUpdatedFilterPredicateGenerator");
    assertContains(text, "Do not manually edit!");
    assertContains(
        text,
        "public class IncrementallyUpdatedFilterPredicateBuilder extends"
            + " IncrementallyUpdatedFilterPredicateBuilderBase {");
  }

  @Test
  void runWritesConstructorDelegatingToSuperClass() throws IOException {
    String text = generate();

    assertContains(
        text,
        lines(
            "public IncrementallyUpdatedFilterPredicateBuilder(List<PrimitiveColumnIO> leaves) {",
            "    super(leaves);",
            "  }"));
  }

  @ParameterizedTest
  @ValueSource(strings = {"Eq", "NotEq", "In", "NotIn", "Contains", "Lt", "LtEq", "Gt", "GtEq"})
  void runWritesVisitMethodForEverySupportedOperator(String operator) throws IOException {
    String text = generate();

    assertContains(
        text,
        "  @Override\n  public <T extends Comparable<T>> IncrementallyUpdatedFilterPredicate visit(" + operator
            + "<T> pred) {\n");
    // Every typed visit method registers the inspector it built on the column path and returns it.
    assertContains(
        text, lines("    addValueInspector(columnPath, valueInspector);", "    return valueInspector;", "  }"));
  }

  @Test
  void runWritesVisitMethodsInOperatorFamilyOrder() throws IOException {
    String text = generate();

    int previous = -1;
    for (String operator : OPERATORS) {
      int index = text.indexOf("IncrementallyUpdatedFilterPredicate visit(" + operator + "<T");
      int current = index;
      assertTrue(current > previous, operator + " visit method is missing or out of order");
      previous = current;
    }
  }

  @ParameterizedTest
  @ValueSource(strings = {"Integer", "Long", "Boolean", "Float", "Double", "Binary"})
  void runWritesTypeBranchForEveryPrimitiveType(String type) throws IOException {
    String text = generate();

    assertEquals(
        BRANCHES_PER_TYPE,
        occurrences(text, "if (clazz.equals(" + type + ".class)) {"),
        () -> "unexpected number of generated type branches for " + type);
  }

  @Test
  void runWritesOneTypeBranchSetPerTypeDispatcher() throws IOException {
    String text = generate();

    assertEquals(
        TYPES.length * BRANCHES_PER_TYPE,
        occurrences(text, "if (clazz.equals("),
        "every type dispatch must cover all primitive types");
    assertEquals(
        11,
        occurrences(text, "\"Encountered unknown type \""),
        "each typed visit method must reject column types it cannot handle");
  }

  @ParameterizedTest
  @CsvSource({"Lt,<", "LtEq,<=", "Gt,>", "GtEq,>="})
  void runRejectsInequalityOperatorsForBooleanColumns(String operator, String symbol) throws IOException {
    String text = generate();

    assertTrue(
        text.contains("      throw new IllegalArgumentException(\"Operator " + symbol
            + " not supported for Boolean\");"),
        () -> operator + " must be rejected for Boolean columns");
    // Boolean columns never reach comparator code: only Eq and NotEq generate a boolean comparison target.
    assertEquals(
        4,
        occurrences(text, "final boolean target = (Boolean) (Object) pred.getValue();"),
        operator + " must not generate comparator logic for Boolean columns");
  }

  @Test
  void runWritesNullSafeEqualityLogicForIntegerColumns() throws IOException {
    String text = generate();

    // Eq: a null predicate value matches every null and never matches a present value.
    assertContains(
        text,
        lines(
            "if (clazz.equals(Integer.class)) {",
            "      if (pred.getValue() == null) {",
            "        valueInspector = new ValueInspector() {",
            "          @Override",
            "          public void updateNull() {",
            "            setResult(true);",
            "          }",
            "",
            "          @Override",
            "          public void update(int value) {",
            "            setResult(false);",
            "          }",
            "        };",
            "      } else {"));
    assertContains(
        text,
        lines(
            "        final int target = (Integer) (Object) pred.getValue();",
            "        final PrimitiveComparator<Integer> comparator = getComparator(columnPath);"));
    assertContains(text, "setResult(comparator.compare(value, target) == 0 );");

    // NotEq is the exact negation: nulls never match and present values are compared for inequality.
    assertContains(
        text,
        lines(
            "if (clazz.equals(Integer.class)) {",
            "      if (pred.getValue() == null) {",
            "        valueInspector = new ValueInspector() {",
            "          @Override",
            "          public void updateNull() {",
            "            setResult(false);",
            "          }",
            "",
            "          @Override",
            "          public void update(int value) {",
            "            setResult(true);",
            "          }",
            "        };",
            "      } else {"));
    assertContains(text, "setResult(comparator.compare(value, target) != 0);");
  }

  @Test
  void runWritesMembershipLogicForInAndNotIn() throws IOException {
    String text = generate();

    assertContains(
        text,
        lines(
            "final Set<Integer> target = (Set<Integer>) pred.getValues();",
            "      final boolean containsNull = target.contains(null);",
            "      final PrimitiveComparator<Integer> comparator = getComparator(columnPath);"));
    assertContains(text, "if (i == null) { continue; }");
    assertContains(text, "if(comparator.compare(value, targetValue) == 0 ) {");
    // In answers the null question with the membership of null, NotIn answers with its negation.
    assertEquals(
        6,
        occurrences(text, "setResult(containsNull);"),
        "In must accept null when the value set contains null");
    assertEquals(
        6,
        occurrences(text, "setResult(!containsNull);"),
        "NotIn must reject null when the value set contains null");
    assertEquals(
        4,
        occurrences(text, "final Set<Boolean> target = (Set<Boolean>) pred.getValues();"),
        "Boolean value sets must be supported by In, NotIn and by their contains variants");
  }

  @Test
  void runWritesComparatorLogicForInequalityOperators() throws IOException {
    String text = generate();

    assertContains(
        text,
        lines(
            "if (clazz.equals(Integer.class)) {",
            "      final int target = (Integer) (Object) pred.getValue();",
            "      final PrimitiveComparator<Integer> comparator = getComparator(columnPath);",
            "",
            "      valueInspector = new ValueInspector() {",
            "        @Override",
            "        public void updateNull() {",
            "          setResult(false);",
            "        }",
            "",
            "        @Override",
            "        public void update(int value) {",
            "          setResult(comparator.compare(value, target) < 0);",
            "        }",
            "      };",
            "    }"));
    assertContains(text, "setResult(comparator.compare(value, target) <= 0);");
    assertContains(text, "setResult(comparator.compare(value, target) > 0);");
    assertContains(text, "setResult(comparator.compare(value, target) >= 0);");
  }

  @Test
  void runWritesUserDefinedPredicateLogic() throws IOException {
    String text = generate();

    assertContains(
        text,
        "  public <T extends Comparable<T>, U extends UserDefinedPredicate<T>> IncrementallyUpdatedFilterPredicate"
            + " visit(UserDefined<T, U> pred) {\n");
    assertContains(text, "final U udp = pred.getUserDefinedPredicate();");
    assertContains(text, "@SuppressWarnings(\"unchecked\")");
    // One branch per primitive type, each delegating the decision to the user defined predicate.
    assertEquals(6, occurrences(text, "setResult(udp.acceptsNullValue());"));
    assertEquals(6, occurrences(text, "setResult(udp.keep((T) (Object) value));"));
  }

  @Test
  void runWritesNegatedUserDefinedPredicateLogic() throws IOException {
    String text = generate();

    assertContains(
        text,
        lines(
            "  public <T extends Comparable<T>, U extends UserDefinedPredicate<T>> IncrementallyUpdatedFilterPredicate"
                + " visit(LogicalNotUserDefined<T, U> notPred) {",
            "    UserDefined<T, U> pred = notPred.getUserDefined();"));
    // Logical negation is applied by the generated inspector, the predicate itself is not modified.
    assertEquals(6, occurrences(text, "setResult(!udp.acceptsNullValue());"));
    assertEquals(6, occurrences(text, "setResult(!udp.keep((T) (Object) value));"));
  }

  @Test
  void runWritesContainsPredicateInfrastructure() throws IOException {
    String text = generate();

    assertContains(text, "private abstract static class ContainsPredicate extends DelegatingValueInspector {");
    assertContains(text, "private static class ContainsSinglePredicate extends ContainsPredicate {");
    assertContains(text, "private static class ContainsAndPredicate extends ContainsPredicate {");
    assertContains(text, "private static class ContainsOrPredicate extends ContainsPredicate {");
    assertContains(
        text, "private class ContainsInspectorVisitor implements FilterPredicate.Visitor<ContainsPredicate> {");
    assertContains(text, "valueInspector = new ContainsInspectorVisitor().visit(pred);");
    assertContains(
        text,
        "return contains.filter(this, ContainsAndPredicate::new, ContainsOrPredicate::new, ContainsPredicate::not);");
    // The eight supported operators are each translated into a single value inspector.
    assertEquals(8, occurrences(text, "return new ContainsSinglePredicate(valueInspector, false);"));
    assertContains(text, "return new ContainsSinglePredicate(getDelegates().iterator().next(), true);");
  }

  @Test
  void runWritesUnsupportedOperatorGuardsForContainsPredicates() throws IOException {
    String text = generate();

    for (String message : new String[] {
      "Operators.And not supported for Contains predicate",
      "Operators.Or not supported for Contains predicate",
      "Operators.Not not supported for Contains predicate",
      "UserDefinedPredicate not supported for Contains predicate",
      "LogicalNotUserDefined not supported for Contains predicate"
    }) {
      assertContains(text, "throw new UnsupportedOperationException(\"" + message + "\");");
    }
  }

  @Test
  void runWritesBalancedJavaSourceEndingWithClosingBrace() throws IOException {
    String text = generate();

    assertTrue(text.length() > 0, "generated source must not be empty");
    int open = occurrences(text, "{");
    int close = occurrences(text, "}");
    assertEquals(open, close, "generated source must contain balanced braces");
    assertTrue(open > 0, "generated source must contain a class body");
    assertTrue(text.endsWith("}\n"), "generated source must end with the closing brace of the class");
    assertEquals(1, occurrences(text, "public class IncrementallyUpdatedFilterPredicateBuilder"));
  }

  @Test
  void runClosesTheWriterSoItCannotBeRunTwice() throws IOException {
    Path target = generatedFile();
    Files.createDirectories(target.getParent());
    IncrementallyUpdatedFilterPredicateGenerator generator =
        new IncrementallyUpdatedFilterPredicateGenerator(target.toFile());

    generator.run();
    long lengthAfterFirstRun = Files.size(target);
    assertTrue(lengthAfterFirstRun > 0, "the first run must produce output");

    assertThrows(IOException.class, generator::run, "the writer must be closed once run() returns");
    assertEquals(
        lengthAfterFirstRun, Files.size(target), "a failing second run must not append to the generated file");
  }

  @Test
  void runProducesIdenticalOutputForRepeatedRuns() throws IOException {
    Path first = generatedFile();
    Files.createDirectories(first.getParent());
    new IncrementallyUpdatedFilterPredicateGenerator(first.toFile()).run();

    Path second = tempDir.resolve("second/IncrementallyUpdatedFilterPredicateBuilder.java");
    Files.createDirectories(second.getParent());
    new IncrementallyUpdatedFilterPredicateGenerator(second.toFile()).run();

    String firstContent = read(first);
    assertTrue(firstContent.length() > 1000, "generated source is suspiciously small");
    assertEquals(firstContent, read(second), "generation must be deterministic");
  }

  @Test
  void constructorTruncatesAnExistingFile() throws IOException {
    Path target = generatedFile();
    Files.createDirectories(target.getParent());
    Files.write(target, "stale content".getBytes(StandardCharsets.UTF_8));

    new IncrementallyUpdatedFilterPredicateGenerator(target.toFile());

    assertEquals(0L, Files.size(target), "binding the generator to a file must truncate it");
  }

  @Test
  void constructorFailsWhenParentDirectoryIsMissing() {
    File target = tempDir.resolve("does/not/exist/Builder.java").toFile();

    assertThrows(FileNotFoundException.class, () -> new IncrementallyUpdatedFilterPredicateGenerator(target));
    assertFalse(target.exists(), "no file must be created when the parent directory is missing");
  }
}

