  /** A trivial in-memory KMS client doing local key wrapping, used to avoid external dependencies. */
  public static class InMemoryLocalWrapKmsClient extends LocalWrapKmsClient {

    @Override
    protected byte[] getMasterKeyFromServer(String masterKeyIdentifier) {
      byte[] masterKey = new byte[16];
      byte[] idBytes = masterKeyIdentifier.getBytes(StandardCharsets.UTF_8);
      System.arraycopy(idBytes, 0, masterKey, 0, Math.min(idBytes.length, masterKey.length));
