  private static ParquetFileReader newReader(SeekableInputStream stream, InternalFileDecryptor fileDecryptor)
      throws IOException {
    MessageType schema = new MessageType("schema");
    FileMetaData fileMetadata = new FileMetaData(
        schema,
        Collections.emptyMap(),
        "test-version",
        fileDecryptor == null ? null : FileMetaData.EncryptionType.PLAINTEXT_FOOTER,
