  private static BloomFilter bloomFilterWithKnownHash() {
    BlockSplitBloomFilter filter = new BlockSplitBloomFilter(BLOOM_FILTER_BYTES);
    filter.insertHash(KNOWN_HASH);
    return filter;
  }

  private static byte[] headerWithUnknownUnionField(int unionFieldOffset) throws IOException {
    byte[] header = serializeHeader(validHeader(BLOOM_FILTER_BYTES));
    // Compact Thrift encodes each nested union field as a field header followed by its value.
    // Changing the field id from 1 (the only supported value) to 2 leaves the union unset.
    header[unionFieldOffset] = 0x2C;
    return header;
  }

  private static BloomFilterHeader validHeader(int numBytes) {
    BloomFilterHeader header = new BloomFilterHeader();
    header.setNumBytes(numBytes);
    BloomFilterAlgorithm algorithm = new BloomFilterAlgorithm();
    algorithm.setBLOCK(new SplitBlockAlgorithm());
    header.setAlgorithm(algorithm);
    BloomFilterHash hash = new BloomFilterHash();
    hash.setXXHASH(new XxHash());
    header.setHash(hash);
    BloomFilterCompression compression = new BloomFilterCompression();
    compression.setUNCOMPRESSED(new Uncompressed());
    header.setCompression(compression);
    return header;
  }

  private static byte[] serializeHeader(BloomFilterHeader header) throws IOException {
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    Util.writeBloomFilterHeader(header, out);
    return out.toByteArray();
  }

  private static byte[] serializeBloomFilter(BloomFilter filter) throws IOException {
    byte[] header = serializeHeader(validHeader(filter.getBitsetSize()));
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    out.write(header);
    filter.writeTo(out);
    return out.toByteArray();
  }

  private static InMemorySeekableInputStream streamWithDataAt(int offset, byte[] data) {
    byte[] fileBytes = new byte[offset + data.length];
    System.arraycopy(data, 0, fileBytes, offset, data.length);
    return new InMemorySeekableInputStream(fileBytes);
  }

  private static final class InMemorySeekableInputStream extends SeekableInputStream {
    private final byte[] data;
    private int position;

    private InMemorySeekableInputStream(byte[] data) {
      this.data = data;
    }

    @Override
    public long getPos() {
      return position;
    }

    @Override
    public void seek(long newPos) throws IOException {
      if (newPos < 0 || newPos > data.length) {
        throw new IOException("Invalid seek position: " + newPos);
      }
      position = (int) newPos;
    }

    @Override
    public int read() {
      if (position >= data.length) {
        return -1;
      }
      return data[position++] & 0xFF;
    }

    @Override
    public int read(byte[] bytes, int start, int length) {
      if (position >= data.length) {
        return -1;
      }
      int bytesToRead = Math.min(length, data.length - position);
      System.arraycopy(data, position, bytes, start, bytesToRead);
      position += bytesToRead;
      return bytesToRead;
    }

    @Override
    public void readFully(byte[] bytes) throws IOException {
      readFully(bytes, 0, bytes.length);
    }

    @Override
    public void readFully(byte[] bytes, int start, int length) throws IOException {
      if (data.length - position < length) {
        throw new EOFException("Not enough bytes in test stream");
      }
      System.arraycopy(data, position, bytes, start, length);
      position += length;
    }

    @Override
    public int read(ByteBuffer buffer) {
      if (!buffer.hasRemaining()) {
        return 0;
      }
      if (position >= data.length) {
        return -1;
      }
      int bytesToRead = Math.min(buffer.remaining(), data.length - position);
      buffer.put(data, position, bytesToRead);
      position += bytesToRead;
      return bytesToRead;
    }

    @Override
    public void readFully(ByteBuffer buffer) throws IOException {
      int length = buffer.remaining();
      if (data.length - position < length) {
        throw new EOFException("Not enough bytes in test stream");
      }
      buffer.put(data, position, length);
      position += length;
    }
  }
}

