/**
 * Tests for {@code ParquetFileReader.Chunk#readAllPages}, the method reading all the pages of a single column chunk
 * out of a byte stream (dictionary page, data pages v1/v2, page checksums and encrypted page headers).
 */
class ParquetFileReaderReadAllPagesTests {

  private static final String COLUMN = "foo";
  private static final byte[] AAD_PREFIX = new byte[] {10, 20, 30, 40};

  @TempDir
  Path tempDir;

  // ---------------------------------------------------------------- normal cases

  @Test
  void readsSingleDataPageV1() throws Exception {
    ParquetFileReader reader = newReader(defaultOptions());
    ColumnChunkMetaData meta = metadata(false, 3L);
    byte[] values = payload(8, 1);

    PageHeader header = dataPageV1Header(3, 12, values.length, null);
    Object chunk = newChunk(reader, meta, buffers(page(header, values)), null, 3L);

    PageReader pages = readAllPages(chunk, null, null, null, -1, -1);

    assertThat(pages.getTotalValueCount()).isEqualTo(3L);
    DataPage page = pages.readPage();
    assertThat(page).isInstanceOf(DataPageV1.class);
    DataPageV1 v1 = (DataPageV1) page;
    assertThat(v1.getValueCount()).isEqualTo(3);
    assertThat(v1.getUncompressedSize()).isEqualTo(12);
    assertThat(v1.getCompressedSize()).isEqualTo(values.length);
    assertThat(v1.getBytes().toByteArray()).isEqualTo(values);
    assertThat(v1.getValueEncoding()).isEqualTo(Encoding.PLAIN);
    assertThat(v1.getDlEncoding()).isEqualTo(Encoding.RLE);
    assertThat(v1.getCrc()).isEmpty();
    assertThat(pages.readPage()).isNull();
  }

  @Test
  void readsDictionaryPageAndFollowingDataPage() throws Exception {
    ParquetFileReader reader = newReader(defaultOptions());
    ColumnChunkMetaData meta = metadata(true, 4L);
    byte[] dictionaryBytes = payload(10, 3);
    byte[] values = payload(9, 5);

    ByteBuffer dictionaryPage = page(dictionaryPageHeader(2, 16, dictionaryBytes.length, null), dictionaryBytes);
    ByteBuffer dataPage = page(dataPageV1Header(4, 20, values.length, null), values);
    Object chunk = newChunk(reader, meta, buffers(dictionaryPage, dataPage), null, 4L);

    PageReader pages = readAllPages(chunk, null, null, null, -1, -1);

    DictionaryPage dictionary = pages.readDictionaryPage();
    assertThat(dictionary).isNotNull();
    assertThat(dictionary.getDictionarySize()).isEqualTo(2);
    assertThat(dictionary.getBytes().toByteArray()).isEqualTo(dictionaryBytes);
    assertThat(dictionary.getEncoding()).isEqualTo(Encoding.PLAIN_DICTIONARY);

    // the dictionary page does not contribute to the value count
    assertThat(pages.getTotalValueCount()).isEqualTo(4L);
    DataPage dataPageV1 = pages.readPage();
    assertThat(dataPageV1).isInstanceOf(DataPageV1.class);
    assertThat(dataPageV1.getValueCount()).isEqualTo(4);
    assertThat(pages.readPage()).isNull();
  }

  @Test
  void readsDataPageV2WithLevelsAndValues() throws Exception {
    ParquetFileReader reader = newReader(defaultOptions());
    ColumnChunkMetaData meta = metadata(false, 5L);
    byte[] repetitionLevels = new byte[] {7};
    byte[] definitionLevels = new byte[] {1, 2};
    byte[] values = payload(3, 11);

    PageHeader header =
        dataPageV2Header(5, 1, 4, definitionLevels.length, repetitionLevels.length, values.length, false, null);
    ByteBuffer page = concat(serialize(header), repetitionLevels, definitionLevels, values);
    Object chunk = newChunk(reader, meta, buffers(page), null, 4L);

    PageReader pages = readAllPages(chunk, null, null, null, -1, -1);

    assertThat(pages.getTotalValueCount()).isEqualTo(5L);
    DataPage dataPage = pages.readPage();
    assertThat(dataPage).isInstanceOf(DataPageV2.class);
    DataPageV2 v2 = (DataPageV2) dataPage;
    assertThat(v2.getValueCount()).isEqualTo(5);
    assertThat(v2.getRowCount()).isEqualTo(4);
    assertThat(v2.getNullCount()).isEqualTo(1);
    assertThat(v2.getRepetitionLevels().toByteArray()).isEqualTo(repetitionLevels);
    assertThat(v2.getDefinitionLevels().toByteArray()).isEqualTo(definitionLevels);
    assertThat(v2.getData().toByteArray()).isEqualTo(values);
    assertThat(v2.isCompressed()).isFalse();
    assertThat(v2.getDataEncoding()).isEqualTo(Encoding.PLAIN);
    assertThat(pages.readPage()).isNull();
  }

  @Test
  void readsSeveralDataPagesV1InOrder() throws Exception {
    ParquetFileReader reader = newReader(defaultOptions());
    ColumnChunkMetaData meta = metadata(false, 6L);
    byte[] firstValues = payload(4, 1);
    byte[] secondValues = payload(6, 2);

    Object chunk = newChunk(
        reader,
        meta,
        buffers(
            page(dataPageV1Header(2, 4, firstValues.length, null), firstValues),
            page(dataPageV1Header(4, 6, secondValues.length, null), secondValues)),
        null,
        6L);

    PageReader pages = readAllPages(chunk, null, null, null, -1, -1);

    assertThat(pages.getTotalValueCount()).isEqualTo(6L);
    DataPage first = pages.readPage();
    DataPage second = pages.readPage();
    assertThat(first.getValueCount()).isEqualTo(2);
    assertThat(((DataPageV1) first).getBytes().toByteArray()).isEqualTo(firstValues);
    assertThat(second.getValueCount()).isEqualTo(4);
    assertThat(((DataPageV1) second).getBytes().toByteArray()).isEqualTo(secondValues);
    assertThat(pages.readPage()).isNull();
  }

  @Test
  void skipsPagesOfUnknownType() throws Exception {
    ParquetFileReader reader = newReader(defaultOptions());
    ColumnChunkMetaData meta = metadata(false, 2L);
    byte[] indexPageContent = payload(5, 9);
    byte[] values = payload(4, 4);

    PageHeader indexHeader = new PageHeader(PageType.INDEX_PAGE, indexPageContent.length, indexPageContent.length);
    Object chunk = newChunk(
        reader,
        meta,
        buffers(page(indexHeader, indexPageContent), page(dataPageV1Header(2, 8, values.length, null), values)),
        null,
        2L);

    PageReader pages = readAllPages(chunk, null, null, null, -1, -1);

    assertThat(pages.getTotalValueCount()).isEqualTo(2L);
    DataPage page = pages.readPage();
    assertThat(page).isInstanceOf(DataPageV1.class);
    assertThat(page.getValueCount()).isEqualTo(2);
    // the skipped page bytes were not mixed into the data page
    assertThat(((DataPageV1) page).getBytes().toByteArray()).isEqualTo(values);
    assertThat(pages.readPage()).isNull();
  }

  @Test
  void chunkWithoutValuesReadsNoPages() throws Exception {
    ParquetFileReader reader = newReader(defaultOptions());
    ColumnChunkMetaData meta = metadata(false, 0L);
    Object chunk = newChunk(reader, meta, buffers(), null, 0L);

    PageReader pages = readAllPages(chunk, null, null, null, -1, -1);

    assertThat(pages.getTotalValueCount()).isZero();
    assertThat(pages.readDictionaryPage()).isNull();
    assertThat(pages.readPage()).isNull();
  }

  @Test
  void noArgOverloadReadsChunk() throws Exception {
    ParquetFileReader reader = newReader(defaultOptions());
    ColumnChunkMetaData meta = metadata(false, 1L);
    byte[] values = payload(3, 2);
    Object chunk =
        newChunk(reader, meta, buffers(page(dataPageV1Header(1, 3, values.length, null), values)), null, 1L);

    Method method = chunk.getClass().getMethod("readAllPages");
    method.setAccessible(true);
    PageReader pages = (PageReader) method.invoke(chunk);

    assertThat(pages.getTotalValueCount()).isEqualTo(1L);
    assertThat(pages.readDictionaryPage()).isNull();
    assertThat(pages.readPage()).isInstanceOf(DataPageV1.class);
    assertThat(pages.readPage()).isNull();
  }

  // ---------------------------------------------------------------- offset index

  @Test
  void offsetIndexDrivesTheNumberOfPagesRead() throws Exception {
    ParquetFileReader reader = newReader(defaultOptions());
    // the metadata value count intentionally does not match the pages, an offset index disables that check
    ColumnChunkMetaData meta = metadata(false, 100L);
    byte[] firstValues = payload(2, 1);
    byte[] secondValues = payload(2, 2);
    byte[] thirdValues = payload(2, 3);
    OffsetIndex offsetIndex = offsetIndex(new long[] {0L, 3L}, 6L);
    Object chunk = newChunk(
        reader,
        meta,
        buffers(
            page(dataPageV1Header(3, 2, firstValues.length, null), firstValues),
            page(dataPageV1Header(3, 2, secondValues.length, null), secondValues),
            page(dataPageV1Header(3, 2, thirdValues.length, null), thirdValues)),
        offsetIndex,
        6L);

    PageReader pages = readAllPages(chunk, null, null, null, -1, -1);

    assertThat(pages.getTotalValueCount()).isEqualTo(6L);
    DataPage first = pages.readPage();
    DataPage second = pages.readPage();
    assertThat(first.getFirstRowIndex()).contains(0L);
    assertThat(first.getIndexRowCount()).contains(3);
    assertThat(second.getFirstRowIndex()).contains(3L);
    assertThat(second.getIndexRowCount()).contains(3);
    assertThat(pages.readPage()).isNull();
  }

  // ---------------------------------------------------------------- invalid input

  @Test
  void moreThanOneDictionaryPageIsRejected() throws Exception {
    ParquetFileReader reader = newReader(defaultOptions());
    ColumnChunkMetaData meta = metadata(true, 2L);
    byte[] dictionaryBytes = payload(4, 8);

    Object chunk = newChunk(
        reader,
        meta,
        buffers(
            page(dictionaryPageHeader(1, 4, dictionaryBytes.length, null), dictionaryBytes),
            page(dictionaryPageHeader(1, 4, dictionaryBytes.length, null), dictionaryBytes)),
        null,
        2L);

    ParquetDecodingException e =
        assertThrows(ParquetDecodingException.class, () -> readAllPages(chunk, null, null, null, -1, -1));
    assertThat(e.getMessage()).startsWith("more than one dictionary page in column");
    assertThat(e.getMessage()).contains(COLUMN);
  }

