  void moreValuesThanDeclaredInTheMetadataFailWithIOException() throws Exception {
    ParquetFileReader reader = newReader(defaultOptions());
    ColumnChunkMetaData meta = metadata(false, 3L);
    byte[] values = payload(4, 1);
    Object chunk =
        newChunk(reader, meta, buffers(page(dataPageV1Header(5, 8, values.length, null), values)), null, 3L);

    IOException e = assertThrows(IOException.class, () -> readAllPages(chunk, null, null, null, -1, -1));
    assertThat(e.getMessage()).contains("Expected 3 values in column chunk at");
    assertThat(e.getMessage()).contains("but got 5 values instead over 1 pages");
  }

