  // ---------------------------------------------------------------- page checksums

  @Test
  void crcVerificationPassesAndCrcIsCopiedToThePages() throws Exception {
    ParquetFileReader reader = newReader(checksumOptions());
    ColumnChunkMetaData meta = metadata(true, 3L);
    byte[] dictionaryBytes = payload(6, 1);
    byte[] values = payload(5, 2);
    int dictionaryCrc = crc(dictionaryBytes);
    int dataCrc = crc(values);

    Object chunk = newChunk(
        reader,
        meta,
        buffers(
            page(dictionaryPageHeader(2, 6, dictionaryBytes.length, dictionaryCrc), dictionaryBytes),
            page(dataPageV1Header(3, 5, values.length, dataCrc), values)),
        null,
        3L);

    PageReader pages = readAllPages(chunk, null, null, null, -1, -1);

    DictionaryPage dictionary = pages.readDictionaryPage();
    assertThat(dictionary.getCrc()).hasValue(dictionaryCrc);
    DataPage page = pages.readPage();
    assertThat(((DataPageV1) page).getCrc()).hasValue(dataCrc);
  }

  @Test
  void crcVerificationPassesForDataPageV2() throws Exception {
    ParquetFileReader reader = newReader(checksumOptions());
    ColumnChunkMetaData meta = metadata(false, 2L);
    byte[] repetitionLevels = new byte[] {3};
    byte[] definitionLevels = new byte[] {4};
    byte[] values = payload(4, 6);
    byte[] wholePage = concatBytes(repetitionLevels, definitionLevels, values);
    int pageCrc = crc(wholePage);

    PageHeader header = dataPageV2Header(
        2, 0, 2, definitionLevels.length, repetitionLevels.length, values.length, false, pageCrc);
    Object chunk = newChunk(reader, meta, buffers(concat(serialize(header), wholePage)), null, 2L);

    PageReader pages = readAllPages(chunk, null, null, null, -1, -1);

    assertThat(pages.getTotalValueCount()).isEqualTo(2L);
    DataPage page = pages.readPage();
    assertThat(page).isInstanceOf(DataPageV2.class);
    assertThat(((DataPageV2) page).getData().toByteArray()).isEqualTo(values);
  }

  @Test
  void corruptChecksumOfDataPageIsDetected() throws Exception {
    ParquetFileReader reader = newReader(checksumOptions());
    ColumnChunkMetaData meta = metadata(false, 3L);
    byte[] values = payload(5, 2);
    int wrongCrc = crc(payload(5, 99));

    Object chunk = newChunk(
        reader, meta, buffers(page(dataPageV1Header(3, 5, values.length, wrongCrc), values)), null, 3L);

    ParquetDecodingException e =
        assertThrows(ParquetDecodingException.class, () -> readAllPages(chunk, null, null, null, -1, -1));
    assertThat(e.getMessage()).isEqualTo("could not verify page integrity, CRC checksum verification failed");
  }

  @Test
  void corruptChecksumOfDictionaryPageIsDetected() throws Exception {
    ParquetFileReader reader = newReader(checksumOptions());
    ColumnChunkMetaData meta = metadata(true, 3L);
    byte[] dictionaryBytes = payload(6, 1);
    int wrongCrc = crc(payload(6, 42));

    Object chunk = newChunk(
        reader,
        meta,
        buffers(page(dictionaryPageHeader(2, 6, dictionaryBytes.length, wrongCrc), dictionaryBytes)),
        null,
        3L);

    ParquetDecodingException e =
        assertThrows(ParquetDecodingException.class, () -> readAllPages(chunk, null, null, null, -1, -1));
    assertThat(e.getMessage())
        .isEqualTo("could not verify dictionary page integrity, CRC checksum verification failed");
  }

  @Test
  void checksumIsNotVerifiedWhenVerificationIsDisabled() throws Exception {
    ParquetFileReader reader = newReader(defaultOptions());
    ColumnChunkMetaData meta = metadata(false, 3L);
    byte[] values = payload(5, 2);
    int wrongCrc = crc(payload(5, 99));

    Object chunk = newChunk(
        reader, meta, buffers(page(dataPageV1Header(3, 5, values.length, wrongCrc), values)), null, 3L);

    PageReader pages = readAllPages(chunk, null, null, null, -1, -1);

    DataPage page = pages.readPage();
    assertThat(page.getValueCount()).isEqualTo(3);
    // the crc is still copied onto the page, it is just not enforced
    assertThat(((DataPageV1) page).getCrc()).isEqualTo(OptionalInt.of(wrongCrc));
  }

  // ---------------------------------------------------------------- encrypted page headers

  @Test
  void headerDecryptorReceivesDictionaryAndDataPageHeaderAad() throws Exception {
    ParquetFileReader reader = newReader(defaultOptions());
    ColumnChunkMetaData meta = metadata(true, 5L);
    byte[] dictionaryBytes = payload(4, 1);
    byte[] firstValues = payload(3, 2);
    byte[] secondValues = payload(3, 3);

    byte[] dictionaryHeader = serialize(dictionaryPageHeader(1, 4, dictionaryBytes.length, null));
    byte[] firstDataHeader = serialize(dataPageV1Header(2, 3, firstValues.length, null));
    byte[] secondDataHeader = serialize(dataPageV1Header(3, 3, secondValues.length, null));

    Object chunk = newChunk(
        reader,
        meta,
        buffers(
            concat(dictionaryHeader, dictionaryBytes),
            concat(firstDataHeader, firstValues),
            concat(secondDataHeader, secondValues)),
        null,
        5L);

    QueuedHeaderDecryptor headerDecryptor =
        new QueuedHeaderDecryptor(dictionaryHeader, firstDataHeader, secondDataHeader);

    PageReader pages = readAllPages(chunk, headerDecryptor, null, AAD_PREFIX, 2, 1);

    assertThat(headerDecryptor.aads).hasSize(3);
    // the dictionary page header uses its own module type and has no page ordinal
    byte[] dictionaryAad = headerDecryptor.aads.get(0);
    assertThat(dictionaryAad).hasSize(AAD_PREFIX.length + 5);
    assertThat(dictionaryAad[AAD_PREFIX.length]).isEqualTo(ModuleType.DictionaryPageHeader.getValue());
    assertThat(Arrays.copyOfRange(dictionaryAad, 0, AAD_PREFIX.length)).isEqualTo(AAD_PREFIX);
    assertThat(Arrays.copyOfRange(dictionaryAad, AAD_PREFIX.length + 1, AAD_PREFIX.length + 3))
        .isEqualTo(new byte[] {2, 0}); // row group ordinal 2, little endian
    assertThat(Arrays.copyOfRange(dictionaryAad, AAD_PREFIX.length + 3, AAD_PREFIX.length + 5))
        .isEqualTo(new byte[] {1, 0}); // column ordinal 1, little endian

    // data page headers carry the data page header module type and a zero based page ordinal
    for (int i = 1; i < 3; i++) {
      byte[] dataAad = headerDecryptor.aads.get(i);
      assertThat(dataAad).hasSize(AAD_PREFIX.length + 7);
      assertThat(dataAad[AAD_PREFIX.length]).isEqualTo(ModuleType.DataPageHeader.getValue());
      assertThat(Arrays.copyOfRange(dataAad, AAD_PREFIX.length + 1, AAD_PREFIX.length + 3))
          .isEqualTo(new byte[] {2, 0});
      assertThat(Arrays.copyOfRange(dataAad, AAD_PREFIX.length + 3, AAD_PREFIX.length + 5))
          .isEqualTo(new byte[] {1, 0});
      assertThat(Arrays.copyOfRange(dataAad, AAD_PREFIX.length + 5, AAD_PREFIX.length + 7))
          .isEqualTo(new byte[] {(byte) (i - 1), 0});
    }

    // the page bodies are still read from the (already decrypted) stream
    assertThat(pages.readDictionaryPage().getBytes().toByteArray()).isEqualTo(dictionaryBytes);
    assertThat(((DataPageV1) pages.readPage()).getBytes().toByteArray()).isEqualTo(firstValues);
    assertThat(((DataPageV1) pages.readPage()).getBytes().toByteArray()).isEqualTo(secondValues);
    assertThat(pages.getTotalValueCount()).isEqualTo(5L);
  }

  @Test
  void headerDecryptorIsNotUsedForDataPageAadWhenMetadataHasNoDictionaryPage() throws Exception {
    ParquetFileReader reader = newReader(defaultOptions());
    ColumnChunkMetaData meta = metadata(false, 2L);
    byte[] values = payload(3, 4);
    byte[] dataHeader = serialize(dataPageV1Header(2, 3, values.length, null));

    Object chunk = newChunk(reader, meta, buffers(concat(dataHeader, values)), null, 2L);
    QueuedHeaderDecryptor headerDecryptor = new QueuedHeaderDecryptor(dataHeader);

    PageReader pages = readAllPages(chunk, headerDecryptor, null, AAD_PREFIX, 0, 0);

    assertThat(headerDecryptor.aads).hasSize(1);
    byte[] dataAad = headerDecryptor.aads.get(0);
    assertThat(dataAad).hasSize(AAD_PREFIX.length + 7);
    assertThat(dataAad[AAD_PREFIX.length]).isEqualTo(ModuleType.DataPageHeader.getValue());
    assertThat(Arrays.copyOfRange(dataAad, AAD_PREFIX.length + 5, AAD_PREFIX.length + 7))
        .isEqualTo(new byte[] {0, 0});
    assertThat(((DataPageV1) pages.readPage()).getBytes().toByteArray()).isEqualTo(values);
  }

  @Test
  void pageOrdinalOfTheOffsetIndexIsUsedForTheDataPageHeaderAad() throws Exception {
    ParquetFileReader reader = newReader(defaultOptions());
    ColumnChunkMetaData meta = metadata(false, 4L);
    byte[] firstValues = payload(2, 1);
    byte[] secondValues = payload(2, 2);
    byte[] firstHeader = serialize(dataPageV1Header(2, 2, firstValues.length, null));
    byte[] secondHeader = serialize(dataPageV1Header(2, 2, secondValues.length, null));

    Object chunk = newChunk(
        reader,
        meta,
        buffers(concat(firstHeader, firstValues), concat(secondHeader, secondValues)),
        offsetIndex(new long[] {0L, 2L}, 4L, 7),
        4L);
    QueuedHeaderDecryptor headerDecryptor = new QueuedHeaderDecryptor(firstHeader, secondHeader);

    readAllPages(chunk, headerDecryptor, null, AAD_PREFIX, 0, 0);

    assertThat(headerDecryptor.aads).hasSize(2);
    for (int i = 0; i < 2; i++) {
      byte[] dataAad = headerDecryptor.aads.get(i);
      assertThat(dataAad[AAD_PREFIX.length]).isEqualTo(ModuleType.DataPageHeader.getValue());
      assertThat(Arrays.copyOfRange(dataAad, AAD_PREFIX.length + 5, AAD_PREFIX.length + 7))
          .isEqualTo(new byte[] {(byte) (7 + i), 0});
    }
  }

  @Test
  void pageDecryptorIsHandedOverToThePageReader() throws Exception {
    ParquetFileReader reader = newReader(defaultOptions());
    ColumnChunkMetaData meta = metadata(false, 4L);
    byte[] values = payload(4, 5);
    byte[] dataHeader = serialize(dataPageV1Header(4, 4, values.length, null));

    Object chunk = newChunk(reader, meta, buffers(concat(dataHeader, values)), null, 4L);
    RecordingPageDecryptor pageDecryptor = new RecordingPageDecryptor();

    PageReader pages = readAllPages(chunk, null, pageDecryptor, AAD_PREFIX, 1, 0);

    // the page is not decrypted while reading the chunk, only when it is handed out by the page reader
    assertThat(pageDecryptor.aads).isEmpty();
    DataPage page = pages.readPage();
    assertThat(((DataPageV1) page).getBytes().toByteArray()).isEqualTo(values);
    assertThat(pageDecryptor.aads).hasSize(1);
    byte[] dataAad = pageDecryptor.aads.get(0);
    assertThat(dataAad).hasSize(AAD_PREFIX.length + 7);
    assertThat(dataAad[AAD_PREFIX.length]).isEqualTo(ModuleType.DataPage.getValue());
    assertThat(Arrays.copyOfRange(dataAad, AAD_PREFIX.length + 5, AAD_PREFIX.length + 7))
        .isEqualTo(new byte[] {0, 0});
  }

  // ---------------------------------------------------------------- helpers

  private ParquetReadOptions defaultOptions() {
    return ParquetReadOptions.builder().build();
  }

  private ParquetReadOptions checksumOptions() {
    return ParquetReadOptions.builder().withPageChecksumVerification(true).build();
  }

  /** Creates a reader over an empty parquet file (only the footer) declaring the {@code foo} column. */
  private ParquetFileReader newReader(ParquetReadOptions options) throws IOException {
    Path file = tempDir.resolve("chunk-reader-" + System.nanoTime() + ".parquet");
    MessageType schema = MessageTypeParser.parseMessageType("message test { required int32 " + COLUMN + "; }");
    try (ParquetFileWriter writer = new ParquetFileWriter(
        new LocalOutputFile(file),
        schema,
        ParquetFileWriter.Mode.OVERWRITE,
        ParquetWriter.DEFAULT_BLOCK_SIZE,
        ParquetWriter.MAX_PADDING_SIZE_DEFAULT)) {
      writer.start();
      writer.end(Collections.<String, String>emptyMap());
    }
    return ParquetFileReader.open(new LocalInputFile(file), options);
  }

  private static ColumnDescriptor column() {
    return new ColumnDescriptor(new String[] {COLUMN}, PrimitiveTypeName.INT32, 0, 0);
  }

  private static ColumnChunkMetaData metadata(boolean hasDictionaryPage, long valueCount) {
    Set<Encoding> encodings = new LinkedHashSet<>();
    encodings.add(Encoding.PLAIN);
    if (hasDictionaryPage) {
      encodings.add(Encoding.RLE_DICTIONARY);
    }
    PrimitiveType type = new PrimitiveType(Repetition.REQUIRED, PrimitiveTypeName.INT32, COLUMN);
    return ColumnChunkMetaData.get(
        ColumnPath.get(COLUMN),
        type,
        CompressionCodecName.UNCOMPRESSED,
        null,
        encodings,
        null,
        4L,
        0L,
        valueCount,
        1024L,
        1024L);
  }

  private static OffsetIndex offsetIndex(long[] firstRowIndexes, long rowCount) {
    return offsetIndex(firstRowIndexes, rowCount, 0);
  }

  private static OffsetIndex offsetIndex(long[] firstRowIndexes, long rowCount, int firstPageOrdinal) {
    return new OffsetIndex() {
      @Override
      public int getPageCount() {
        return firstRowIndexes.length;
      }

      @Override
      public long getOffset(int pageIndex) {
        return 0L;
      }

      @Override
      public int getCompressedPageSize(int pageIndex) {
        return 0;
      }

      @Override
      public long getFirstRowIndex(int pageIndex) {
        return firstRowIndexes[pageIndex];
      }

      @Override
      public int getPageOrdinal(int pageIndex) {
        return firstPageOrdinal + pageIndex;
      }
    };
  }

  /** Instantiates the (private) {@code ParquetFileReader.Chunk} for the given chunk content. */
  private static Object newChunk(
      ParquetFileReader reader,
      ColumnChunkMetaData metadata,
      List<ByteBuffer> buffers,
      OffsetIndex offsetIndex,
      long rowCount)
      throws Exception {
    Class<?> descriptorClass = Class.forName("org.apache.parquet.hadoop.ParquetFileReader$ChunkDescriptor");
    Constructor<?> descriptorConstructor = descriptorClass.getDeclaredConstructor(
        ColumnDescriptor.class, ColumnChunkMetaData.class, long.class, long.class);
    descriptorConstructor.setAccessible(true);
    Object descriptor = descriptorConstructor.newInstance(column(), metadata, 0L, 1024L);

    Class<?> chunkClass = Class.forName("org.apache.parquet.hadoop.ParquetFileReader$Chunk");
    Constructor<?> chunkConstructor = chunkClass.getDeclaredConstructor(
        ParquetFileReader.class, descriptorClass, List.class, OffsetIndex.class, long.class);
    chunkConstructor.setAccessible(true);
    return chunkConstructor.newInstance(reader, descriptor, buffers, offsetIndex, rowCount);
  }

  private static PageReader readAllPages(
      Object chunk,
      BlockCipher.Decryptor headerBlockDecryptor,
      BlockCipher.Decryptor pageBlockDecryptor,
      byte[] aadPrefix,
      int rowGroupOrdinal,
      int columnOrdinal)
      throws Exception {
    Method method = chunk.getClass()
        .getMethod(
            "readAllPages",
            BlockCipher.Decryptor.class,
            BlockCipher.Decryptor.class,
            byte[].class,
            int.class,
            int.class);
    method.setAccessible(true);
    try {
      return (PageReader) method.invoke(
          chunk, headerBlockDecryptor, pageBlockDecryptor, aadPrefix, rowGroupOrdinal, columnOrdinal);
    } catch (InvocationTargetException e) {
      Throwable cause = e.getCause();
      if (cause instanceof Exception) {
        throw (Exception) cause;
      }
      if (cause instanceof Error) {
        throw (Error) cause;
      }
      throw e;
    }
  }

  private static PageHeader dataPageV1Header(int numValues, int uncompressedSize, int compressedSize, Integer crc) {
    PageHeader header = new PageHeader(PageType.DATA_PAGE, uncompressedSize, compressedSize);
    header.setData_page_header(new DataPageHeader(
        numValues,
        org.apache.parquet.format.Encoding.PLAIN,
        org.apache.parquet.format.Encoding.RLE,
        org.apache.parquet.format.Encoding.BIT_PACKED));
    if (crc != null) {
      header.setCrc(crc);
    }
    return header;
  }

  private static PageHeader dataPageV2Header(
      int numValues,
      int numNulls,
      int numRows,
      int definitionLevelsByteLength,
      int repetitionLevelsByteLength,
      int valuesByteLength,
      boolean isCompressed,
      Integer crc) {
    int uncompressedSize = repetitionLevelsByteLength + definitionLevelsByteLength + valuesByteLength;
    PageHeader header = new PageHeader(PageType.DATA_PAGE_V2, uncompressedSize, uncompressedSize);
    header.setData_page_header_v2(new DataPageHeaderV2(
        numValues,
        numNulls,
        numRows,
        org.apache.parquet.format.Encoding.PLAIN,
        definitionLevelsByteLength,
        repetitionLevelsByteLength));
    header.getData_page_header_v2().setIs_compressed(isCompressed);
    if (crc != null) {
      header.setCrc(crc);
    }
    return header;
  }

  private static PageHeader dictionaryPageHeader(
      int numValues, int uncompressedSize, int compressedSize, Integer crc) {
    PageHeader header = new PageHeader(PageType.DICTIONARY_PAGE, uncompressedSize, compressedSize);
    header.setDictionary_page_header(
        new DictionaryPageHeader(numValues, org.apache.parquet.format.Encoding.PLAIN_DICTIONARY));
    if (crc != null) {
      header.setCrc(crc);
    }
    return header;
  }

  private static byte[] serialize(PageHeader header) throws IOException {
    ByteArrayOutputStream out = new ByteArrayOutputStream();
    Util.writePageHeader(header, out);
    return out.toByteArray();
  }

  private static ByteBuffer page(PageHeader header, byte[] payload) throws IOException {
    return concat(serialize(header), payload);
  }

  private static ByteBuffer concat(byte[]... parts) {
    return ByteBuffer.wrap(concatBytes(parts));
  }

  private static byte[] concatBytes(byte[]... parts) {
    int size = 0;
    for (byte[] part : parts) {
      size += part.length;
    }
    byte[] result = new byte[size];
    int offset = 0;
    for (byte[] part : parts) {
      System.arraycopy(part, 0, result, offset, part.length);
      offset += part.length;
    }
    return result;
  }

  private static List<ByteBuffer> buffers(ByteBuffer... pages) {
    return new ArrayList<>(Arrays.asList(pages));
  }

  private static byte[] payload(int size, int seed) {
    byte[] bytes = new byte[size];
    for (int i = 0; i < size; i++) {
      bytes[i] = (byte) (seed + i);
    }
    return bytes;
  }

  private static int crc(byte[] bytes) {
    CRC32 crc = new CRC32();
    crc.update(bytes);
    return (int) crc.getValue();
  }

  /** Decryptor returning pre-serialized page headers, as if they were decrypted from the stream. */
  private static final class QueuedHeaderDecryptor implements BlockCipher.Decryptor {
    private final Iterator<byte[]> headers;
    private final List<byte[]> aads = new ArrayList<>();

    QueuedHeaderDecryptor(byte[]... headers) {
      this.headers = Arrays.asList(headers).iterator();
    }

    @Override
    public byte[] decrypt(byte[] lengthAndCiphertext, byte[] aad) {
      throw new UnsupportedOperationException("a page header is decrypted from the stream");
    }

    @Override
    public ByteBuffer decrypt(ByteBuffer from, byte[] aad) {
      throw new UnsupportedOperationException("a page header is decrypted from the stream");
    }

    @Override
    public byte[] decrypt(InputStream from, byte[] aad) throws IOException {
      aads.add(aad == null ? null : aad.clone());
      if (!headers.hasNext()) {
        throw new IOException("unexpected request to decrypt another page header");
      }
      byte[] header = headers.next();
      byte[] consumed = new byte[header.length];
      int offset = 0;
      while (offset < consumed.length) {
        int read = from.read(consumed, offset, consumed.length - offset);
        if (read < 0) {
          throw new IOException("unexpected end of the chunk stream");
        }
        offset += read;
      }
      return header;
    }
  }

  /** Decryptor returning the input unchanged, recording the AAD of every page it is asked to decrypt. */
  private static final class RecordingPageDecryptor implements BlockCipher.Decryptor {
    private final List<byte[]> aads = new ArrayList<>();

    @Override
    public byte[] decrypt(byte[] lengthAndCiphertext, byte[] aad) {
      aads.add(aad == null ? null : aad.clone());
      return lengthAndCiphertext;
    }

    @Override
    public ByteBuffer decrypt(ByteBuffer from, byte[] aad) {
      throw new UnsupportedOperationException("on-heap buffers are used");
    }

    @Override
    public byte[] decrypt(InputStream from, byte[] aad) {
      throw new UnsupportedOperationException("a data page is decrypted from a byte array");
    }
  }
}

