    configuration.set(ParquetOutputFormat.JOB_SUMMARY_LEVEL, JobSummaryLevel.ALL.name());
    Path firstDataFile = writeParquetFile("part-00000.parquet");
    Path secondDataFile = writeParquetFile("part-00001.parquet");
    int expectedBlockCount = readMetadata(firstDataFile).getBlocks().size()
        + readMetadata(secondDataFile).getBlocks().size();

    ParquetOutputCommitter.writeMetaDataFile(configuration, outputPath);

    Path metadataFile = new Path(outputPath, ParquetFileWriter.PARQUET_METADATA_FILE);
    Path commonMetadataFile = new Path(outputPath, ParquetFileWriter.PARQUET_COMMON_METADATA_FILE);
    FileSystem fileSystem = outputPath.getFileSystem(configuration);

    assertThat(fileSystem.exists(metadataFile)).isTrue();
    assertThat(fileSystem.exists(commonMetadataFile)).isTrue();

    ParquetMetadata metadata = readMetadata(metadataFile);
    ParquetMetadata commonMetadata = readMetadata(commonMetadataFile);
    assertThat(expectedBlockCount).isPositive();
    assertThat(metadata.getBlocks()).hasSize(expectedBlockCount);
    assertThat(commonMetadata.getBlocks()).isEmpty();
    assertThat(metadata.getFileMetaData().getSchema()).isEqualTo(SCHEMA);
    assertThat(commonMetadata.getFileMetaData().getSchema()).isEqualTo(SCHEMA);
