    assertThat(ParquetOutputFormat.getJobSummaryLevel(configuration)).isEqualTo(JobSummaryLevel.ALL);
    writeParquetFile("part-00000.parquet");

    ParquetOutputCommitter.writeMetaDataFile(configuration, outputPath);

    FileSystem fileSystem = outputPath.getFileSystem(configuration);
    assertThat(fileSystem.exists(new Path(outputPath, ParquetFileWriter.PARQUET_METADATA_FILE)))
