    Files.writeString(tempDir.resolve(ParquetFileWriter.PARQUET_COMMON_METADATA_FILE), "common-sentinel");

    ParquetOutputCommitter.writeMetaDataFile(configuration, outputPath);

    assertThat(Files.readString(tempDir.resolve(ParquetFileWriter.PARQUET_METADATA_FILE)))
        .isEqualTo("metadata-sentinel");
    assertThat(Files.readString(tempDir.resolve(ParquetFileWriter.PARQUET_COMMON_METADATA_FILE)))
        .isEqualTo("common-sentinel");
