    configuration.set(ParquetOutputFormat.JOB_SUMMARY_LEVEL, JobSummaryLevel.ALL.name());
    java.nio.file.Path missing = tempDir.resolve("missing-directory");
    Path missingOutputPath = new Path(missing.toUri());

    assertThatCode(() -> ParquetOutputCommitter.writeMetaDataFile(configuration, missingOutputPath))
        .doesNotThrowAnyException();

    assertThat(Files.exists(missing)).isFalse();
