  @Test
  void propagatesInvalidSummaryLevelBeforeAccessingTheOutputPath() {
    configuration.set(ParquetOutputFormat.JOB_SUMMARY_LEVEL, "not-a-summary-level");

    assertThatThrownBy(() -> ParquetOutputCommitter.writeMetaDataFile(configuration, outputPath))
        .isInstanceOf(IllegalArgumentException.class)
        .hasMessageContaining("NOT-A-SUMMARY-LEVEL");
