    configuration.set(ParquetOutputFormat.JOB_SUMMARY_LEVEL, JobSummaryLevel.ALL.name());
    Path dataFile = writeParquetFile("part-00000.parquet");
    Files.createDirectory(tempDir.resolve(ParquetFileWriter.PARQUET_METADATA_FILE));
    Files.createDirectory(tempDir.resolve(ParquetFileWriter.PARQUET_COMMON_METADATA_FILE));

    ParquetOutputCommitter.writeMetaDataFile(configuration, outputPath);

    FileSystem fileSystem = outputPath.getFileSystem(configuration);
    assertThat(fileSystem.exists(new Path(outputPath, ParquetFileWriter.PARQUET_METADATA_FILE)))
        .isFalse();
