import org.apache.parquet.example.data.Group;
import org.apache.parquet.example.data.simple.SimpleGroup;
import org.apache.parquet.hadoop.IndexCache;
import org.apache.parquet.hadoop.ParquetFileReader;
import org.apache.parquet.hadoop.ParquetReader;
import org.apache.parquet.hadoop.ParquetWriter;
import org.apache.parquet.hadoop.example.ExampleParquetWriter;
import org.apache.parquet.hadoop.example.GroupReadSupport;
import org.apache.parquet.hadoop.metadata.BlockMetaData;
import org.apache.parquet.hadoop.metadata.CompressionCodecName;
import org.apache.parquet.hadoop.metadata.ParquetMetadata;
import org.apache.parquet.hadoop.util.HadoopInputFile;
import org.apache.parquet.schema.MessageType;
import org.apache.parquet.schema.MessageTypeParser;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class ParquetRewriterProcessBlocksTests {

  private static final MessageType MAIN_SCHEMA = MessageTypeParser.parseMessageType(
      "message main {\n"
          + "  required int32 id;\n"
          + "  optional binary name (UTF8);\n"
          + "}");

  private static final MessageType JOIN_SCHEMA = MessageTypeParser.parseMessageType(
      "message joined {\n"
          + "  required int32 id;\n"
          + "  optional binary name (UTF8);\n"
          + "  optional int64 score;\n"
          + "}");

  @TempDir
  java.nio.file.Path tempDir;

  private final Configuration conf = new Configuration();

  @Test
  void rewritesOneFileAndPreservesEveryRowGroup() throws Exception {
    Path input = writeMainFile("single-input.parquet", 1, mainRow(1, "one"), mainRow(2, "two"), mainRow(3, "three"));
    Path output = outputPath("single-output.parquet");

    try (ParquetRewriter rewriter =
        new ParquetRewriter(new RewriteOptions.Builder(conf, input, output).build())) {
      rewriter.processBlocks();
    }

    ParquetMetadata metadata = readMetadata(output);
    assertThat(metadata.getBlocks()).hasSize(3);
    assertThat(metadata.getBlocks())
        .extracting(BlockMetaData::getRowCount)
        .containsExactly(1L, 1L, 1L);

    List<Group> rows = readAll(output);
    assertThat(rows).hasSize(3);
    assertThat(rows).extracting(group -> group.getInteger("id", 0)).containsExactly(1, 2, 3);
    assertThat(rows).extracting(group -> group.getString("name", 0)).containsExactly("one", "two", "three");
  }

  @Test
  void mergesMultipleInputFilesInQueueOrder() throws Exception {
    Path first = writeMainFile("merge-first.parquet", 1, mainRow(10, "ten"), mainRow(11, "eleven"));
    Path second = writeMainFile("merge-second.parquet", 1, mainRow(20, "twenty"), mainRow(21, "twenty-one"));
    Path output = outputPath("merged.parquet");

    try (ParquetRewriter rewriter = new ParquetRewriter(
        new RewriteOptions.Builder(conf, Arrays.asList(first, second), output)
            .indexCacheStrategy(IndexCache.CacheStrategy.PREFETCH_BLOCK)
            .build())) {
      rewriter.processBlocks();
    }

    assertThat(readMetadata(output).getBlocks())
        .extracting(BlockMetaData::getRowCount)
        .containsExactly(1L, 1L, 1L, 1L);
    List<Group> rows = readAll(output);
    assertThat(rows).extracting(group -> group.getInteger("id", 0)).containsExactly(10, 11, 20, 21);
    assertThat(rows)
        .extracting(group -> group.getString("name", 0))
        .containsExactly("ten", "eleven", "twenty", "twenty-one");
  }

  @Test
  void processesOnlyTheColumnsThatSurvivePruning() throws Exception {
    Path input = writeMainFile("prune-input.parquet", 1, mainRow(7, "seventh"), mainRow(8, "eighth"));
    Path output = outputPath("pruned.parquet");

    try (ParquetRewriter rewriter = new ParquetRewriter(
        new RewriteOptions.Builder(conf, input, output).prune(List.of("name")).build())) {
      rewriter.processBlocks();
    }

    MessageType outputSchema = readMetadata(output).getFileMetaData().getSchema();
    assertThat(outputSchema.getFieldCount()).isEqualTo(1);
    assertThat(outputSchema.getFieldName(0)).isEqualTo("id");

    List<Group> rows = readAll(output);
    assertThat(rows).extracting(group -> group.getInteger("id", 0)).containsExactly(7, 8);
    assertThat(rows).allSatisfy(group -> assertThat(group.getType().getFieldCount()).isEqualTo(1));
  }

  @Test
  void reencodesEveryColumnWhenATransformCodecIsRequested() throws Exception {
    Path input = writeMainFile("codec-input.parquet", 10, mainRow(1, "first"), mainRow(2, "second"));
    Path output = outputPath("codec-output.parquet");

    try (ParquetRewriter rewriter = new ParquetRewriter(
        new RewriteOptions.Builder(conf, input, output)
            .transform(CompressionCodecName.GZIP)
            .build())) {
      rewriter.processBlocks();
    }

    ParquetMetadata metadata = readMetadata(output);
    assertThat(metadata.getBlocks()).hasSize(1);
    assertThat(metadata.getBlocks())
        .allSatisfy(block -> assertThat(block.getColumns())
            .allSatisfy(column -> assertThat(column.getCodec()).isEqualTo(CompressionCodecName.GZIP)));
    assertThat(readAll(output)).extracting(group -> group.getInteger("id", 0)).containsExactly(1, 2);
  }

  @Test
  void appendsJoinOnlyColumnsAndKeepsMainColumnsByDefault() throws Exception {
    Path input = writeMainFile("join-main.parquet", 10, mainRow(1, "from-main-1"), mainRow(2, "from-main-2"));
    Path inputToJoin = writeJoinFile(
        "join-right.parquet", 10, joinRow(1, "from-join-1", 101L), joinRow(2, "from-join-2", 102L));
    Path output = outputPath("joined.parquet");

    try (ParquetRewriter rewriter = new ParquetRewriter(
        new RewriteOptions.Builder(conf, input, inputToJoin, output).build())) {
      rewriter.processBlocks();
    }

    MessageType schema = readMetadata(output).getFileMetaData().getSchema();
    assertThat(schema.getFieldCount()).isEqualTo(3);
    assertThat(schema.getFieldName(0)).isEqualTo("id");
    assertThat(schema.getFieldName(1)).isEqualTo("name");
    assertThat(schema.getFieldName(2)).isEqualTo("score");

    List<Group> rows = readAll(output);
    assertThat(rows).extracting(group -> group.getInteger("id", 0)).containsExactly(1, 2);
    assertThat(rows)
        .extracting(group -> group.getString("name", 0))
        .containsExactly("from-main-1", "from-main-2");
    assertThat(rows).extracting(group -> group.getLong("score", 0)).containsExactly(101L, 102L);
  }

  @Test
  void joinColumnsCanOverwriteMatchingMainColumns() throws Exception {
    Path input = writeMainFile("overwrite-main.parquet", 10, mainRow(1, "main-value"));
    Path inputToJoin = writeJoinFile("overwrite-join.parquet", 10, joinRow(1, "join-value", 55L));
    Path output = outputPath("overwritten.parquet");

    try (ParquetRewriter rewriter = new ParquetRewriter(
        new RewriteOptions.Builder(conf, input, inputToJoin, output)
            .overwriteInputWithJoinColumns(true)
            .build())) {
      rewriter.processBlocks();
    }

    List<Group> rows = readAll(output);
    assertThat(rows).hasSize(1);
    assertThat(rows.get(0).getString("name", 0)).isEqualTo("join-value");
    assertThat(rows.get(0).getLong("score", 0)).isEqualTo(55L);
  }

  @Test
  void advancesThroughMultipleJoinReadersAsMainInputFilesAreProcessed() throws Exception {
    Path first = writeMainFile("multi-join-main-1.parquet", 10, mainRow(1, "main-1"));
    Path second = writeMainFile("multi-join-main-2.parquet", 10, mainRow(2, "main-2"));
    Path firstJoin = writeJoinFile("multi-join-right-1.parquet", 10, joinRow(1, "join-1", 11L));
    Path secondJoin = writeJoinFile("multi-join-right-2.parquet", 10, joinRow(2, "join-2", 22L));
    Path output = outputPath("multi-joined.parquet");

    try (ParquetRewriter rewriter = new ParquetRewriter(
        new RewriteOptions.Builder(
                conf, Arrays.asList(first, second), Arrays.asList(firstJoin, secondJoin), output)
            .build())) {
      rewriter.processBlocks();
    }

    assertThat(readMetadata(output).getBlocks()).hasSize(2);
    List<Group> rows = readAll(output);
    assertThat(rows).extracting(group -> group.getInteger("id", 0)).containsExactly(1, 2);
    assertThat(rows)
        .extracting(group -> group.getString("name", 0))
        .containsExactly("main-1", "main-2");
    assertThat(rows).extracting(group -> group.getLong("score", 0)).containsExactly(11L, 22L);
  }

  @Test
  void handlesInputWithoutAnyRowGroups() throws Exception {
    Path input = writeMainFile("empty-input.parquet", 10);
    Path output = outputPath("empty-output.parquet");

    try (ParquetRewriter rewriter =
        new ParquetRewriter(new RewriteOptions.Builder(conf, input, output).build())) {
      rewriter.processBlocks();
    }

    assertThat(readMetadata(output).getBlocks()).isEmpty();
    assertThat(readAll(output)).isEmpty();
  }

  @Test
  void propagatesIOExceptionWhenARequiredColumnIsNullified() throws Exception {
    Path input = writeMainFile("nullify-required.parquet", 10, mainRow(1, "value"));
    Path output = outputPath("nullify-required-output.parquet");

    assertThatThrownBy(() -> {
          try (ParquetRewriter rewriter = new ParquetRewriter(new RewriteOptions.Builder(conf, input, output)
              .mask(Map.of("id", MaskMode.NULLIFY))
              .build())) {
            rewriter.processBlocks();
          }
        })
        .isInstanceOf(IOException.class)
        .hasMessageContaining("Required column [id] cannot be nullified");
  }

  @Test
  void secondInvocationDoesNotRewriteOrDuplicateBlocks() throws Exception {
    Path input = writeMainFile("repeat-input.parquet", 10, mainRow(42, "answer"));
    Path output = outputPath("repeat-output.parquet");

    try (ParquetRewriter rewriter =
        new ParquetRewriter(new RewriteOptions.Builder(conf, input, output).build())) {
      rewriter.processBlocks();
      rewriter.processBlocks();
    }

    ParquetMetadata metadata = readMetadata(output);
    assertThat(metadata.getBlocks()).hasSize(1);
    assertThat(metadata.getBlocks().get(0).getRowCount()).isEqualTo(1L);
    assertThat(readAll(output)).extracting(group -> group.getInteger("id", 0)).containsExactly(42);
  }

  private Path writeMainFile(String name, int rowGroupRowCountLimit, Group... rows) throws IOException {
    return writeFile(name, MAIN_SCHEMA, rowGroupRowCountLimit, Arrays.asList(rows));
  }

  private Path writeJoinFile(String name, int rowGroupRowCountLimit, Group... rows) throws IOException {
    return writeFile(name, JOIN_SCHEMA, rowGroupRowCountLimit, Arrays.asList(rows));
  }

  private Path writeFile(String name, MessageType schema, int rowGroupRowCountLimit, List<Group> rows)
      throws IOException {
    Path path = inputPath(name);
    try (ParquetWriter<Group> writer = ExampleParquetWriter.builder(path)
        .withType(schema)
        .withConf(conf)
        .withCompressionCodec(CompressionCodecName.UNCOMPRESSED)
        .withRowGroupRowCountLimit(rowGroupRowCountLimit)
        .build()) {
      for (Group row : rows) {
        writer.write(row);
      }
    }
    return path;
  }

  private Group mainRow(int id, String name) {
    SimpleGroup group = new SimpleGroup(MAIN_SCHEMA);
    group.add("id", id);
    group.add("name", name);
    return group;
  }

  private Group joinRow(int id, String name, long score) {
    SimpleGroup group = new SimpleGroup(JOIN_SCHEMA);
    group.add("id", id);
    group.add("name", name);
    group.add("score", score);
    return group;
  }

  private List<Group> readAll(Path path) throws IOException {
    List<Group> rows = new ArrayList<>();
    try (ParquetReader<Group> reader = ParquetReader.builder(new GroupReadSupport(), path)
        .withConf(conf)
        .build()) {
      Group group;
      while ((group = reader.read()) != null) {
        rows.add(group);
      }
    }
    return rows;
  }

  private ParquetMetadata readMetadata(Path path) throws IOException {
    try (ParquetFileReader reader = ParquetFileReader.open(HadoopInputFile.fromPath(path, conf))) {
      return reader.getFooter();
    }
  }

  private Path inputPath(String name) throws IOException {
    java.nio.file.Path directory = tempDir.resolve("input");
    Files.createDirectories(directory);
    return new Path(directory.resolve(name).toUri());
  }

  private Path outputPath(String name) throws IOException {
    java.nio.file.Path directory = tempDir.resolve("output");
    Files.createDirectories(directory);
    return new Path(directory.resolve(name).toUri());
  }
}
